def find_longest_word(sentence):
    if not sentence:
        return ""

    words = sentence.split()
    if not words:
        return ""

    longest_word = ""
    max_length = 0

    for word in words:
        current_word_length = len(word)
        if current_word_length > max_length:
            max_length = current_word_length
            longest_word = word

    return longest_word

