def merge_dictionaries(dict1, dict2):
    merged_dict = dict1.copy()
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict

def test_merge_dictionaries():
    # Test case 1: No overlapping keys
    d1 = {'a': 1, 'b': 2}
    d2 = {'c': 3, 'd': 4}
    expected = {'a': 1, 'b': 2, 'c': 3, 'd': 4}
    result = merge_dictionaries(d1, d2)
    assert result == expected, f"Test 1 failed: Expected {expected}, got {result}"

    # Test case 2: Overlapping keys, dict2 overrides
    d3 = {'x': 10, 'y': 20}
    d4 = {'y': 25, 'z': 30}
    expected = {'x': 10, 'y': 25, 'z': 30}
    result = merge_dictionaries(d3, d4)
    assert result == expected, f"Test 2 failed: Expected {expected}, got {result}"

    # Test case 3: Empty first dictionary
    d5 = {}
    d6 = {'p': 1, 'q': 2}
    expected = {'p': 1, 'q': 2}
    result = merge_dictionaries(d5, d6)
    assert result == expected, f"Test 3 failed: Expected {expected}, got {result}"

    # Test case 4: Empty second dictionary
    d7 = {'r': 100, 's': 200}
    d8 = {}
    expected = {'r': 100, 's': 200}
    result = merge_dictionaries(d7, d8)
    assert result == expected, f"Test 4 failed: Expected {expected}, got {result}"

    # Test case 5: Both dictionaries empty
    d9 = {}
    d10 = {}
    expected = {}
    result = merge_dictionaries(d9, d10)
    assert result == expected, f"Test 5 failed: Expected {expected}, got {result}"

    print("All merge_dictionaries tests passed!")

if __name__ == "__main__":
    test_merge_dictionaries()

