def validate_email(email):
    if not isinstance(email, str):
        return False

    if '@' not in email:
        return False

    if '.' not in email:
        return False

    at_index = email.find('@')
    dot_index = email.rfind('.')

    if at_index == 0 or at_index == len(email) - 1:
        return False

    if dot_index == 0 or dot_index == len(email) - 1:
        return False

    if at_index > dot_index:
        return False

    # Check for consecutive dots or dots immediately after @
    if '..' in email:
        return False

    if email[at_index + 1] == '.':
        return False

    return True

