def update_inventory(inventory, item_name, quantity):
    if item_name in inventory:
        inventory[item_name] += quantity
    else:
        inventory[item_name] = quantity
    return inventory

def test_update_inventory():
    # Test case 1: Item already exists
    initial_inventory_1 = {'apple': 10, 'banana': 5}
    expected_inventory_1 = {'apple': 15, 'banana': 5}
    result_inventory_1 = update_inventory(initial_inventory_1, 'apple', 5)
    assert result_inventory_1 == expected_inventory_1, f"Test Case 1 Failed: Expected {expected_inventory_1}, Got {result_inventory_1}"

    # Test case 2: New item
    initial_inventory_2 = {'apple': 10}
    expected_inventory_2 = {'apple': 10, 'banana': 3}
    result_inventory_2 = update_inventory(initial_inventory_2, 'banana', 3)
    assert result_inventory_2 == expected_inventory_2, f"Test Case 2 Failed: Expected {expected_inventory_2}, Got {result_inventory_2}"

    # Test case 3: Adding zero quantity to existing item
    initial_inventory_3 = {'orange': 7}
    expected_inventory_3 = {'orange': 7}
    result_inventory_3 = update_inventory(initial_inventory_3, 'orange', 0)
    assert result_inventory_3 == expected_inventory_3, f"Test Case 3 Failed: Expected {expected_inventory_3}, Got {result_inventory_3}"

    # Test case 4: Adding zero quantity to new item (should add with 0)
    initial_inventory_4 = {'grape': 12}
    expected_inventory_4 = {'grape': 12, 'kiwi': 0}
    result_inventory_4 = update_inventory(initial_inventory_4, 'kiwi', 0)
    assert result_inventory_4 == expected_inventory_4, f"Test Case 4 Failed: Expected {expected_inventory_4}, Got {result_inventory_4}"

    # Test case 5: Empty initial inventory, add new item
