    expected_inventory_5 = {'milk': 2}
    result_inventory_5 = update_inventory(initial_inventory_5, 'milk', 2)
    assert result_inventory_5 == expected_inventory_5, f"Test Case 5 Failed: Expected {expected_inventory_5}, Got {result_inventory_5}"

    print("All test cases passed!")

