def capitalize_sentences(text):
    if not text:
        return ""

    sentences = []
    current_sentence_start = 0
    for i, char in enumerate(text):
        if char in ['.', '!', '?']:
            sentences.append(text[current_sentence_start : i + 1].strip())
            current_sentence_start = i + 1

    if current_sentence_start < len(text):
        sentences.append(text[current_sentence_start:].strip())

    capitalized_sentences = []
    for sentence in sentences:
        if sentence:
            capitalized_sentences.append(sentence[0].upper() + sentence[1:])
        else:
            capitalized_sentences.append("")

    return " ".join(capitalized_sentences).strip()

