def calculate_grade(score):
    if not isinstance(score, (int, float)):
        raise TypeError("Score must be a number.")
    if not (0 <= score <= 100):
        raise ValueError("Score must be between 0 and 100.")

    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

def main():
    test_scores = [95, 82, 77, 60, 55, 100, 0]
    for s in test_scores:
        grade = calculate_grade(s)
        print(f"Score: {s}, Grade: {grade}")

    # Example of handling edge cases or invalid input
    try:
        print(f"Score: 101, Grade: {calculate_grade(101)}")
    except ValueError as e:
        print(f"Error for score 101: {e}")

    try:
        print(f"Score: -5, Grade: {calculate_grade(-5)}")
    except ValueError as e:
        print(f"Error for score -5: {e}")

    try:
