def is_leap_year(year):
    """
    Determines if a given year is a leap year according to the Gregorian calendar rules.

    Args:
        year (int): The year to check.

    Returns:
        bool: True if the year is a leap year, False otherwise.
    """
    if not isinstance(year, int):
        raise TypeError("Year must be an integer.")
    if year < 0:
        raise ValueError("Year must be a non-negative integer.")

    is_divisible_by_4 = (year % 4 == 0)
    is_divisible_by_100 = (year % 100 == 0)
    is_divisible_by_400 = (year % 400 == 0)

    if is_divisible_by_4:
        if is_divisible_by_100:
            if is_divisible_by_400:
                return True
            else:
                return False
        else:
            return True
    else:
        return False

