def decimal_to_binary(decimal_int):
    if decimal_int == 0:
        return '0'

    binary_string_parts = []
    current_value = decimal_int

    while current_value > 0:
        remainder = current_value % 2
        binary_string_parts.append(str(remainder))
        current_value //= 2

    # The bits were appended in reverse order, so we need to reverse the list
    binary_string_parts.reverse()

    # Join the list of characters to form the final binary string
    return "".join(binary_string_parts)

