    decrypted_text = []
    for char in text:
        if 'a' <= char <= 'z':
            start_ascii = ord('a')
            char_code = ord(char)
            shifted_code = char_code - start_ascii
            decrypted_code = (shifted_code - shift) % 26
            final_code = decrypted_code + start_ascii
            decrypted_char = chr(final_code)
            decrypted_text.append(decrypted_char)
