def sort_dict_by_key(input_dict: dict) -> dict:
    if not isinstance(input_dict, dict):
        raise TypeError("Input must be a dictionary.")

    sorted_items = sorted(input_dict.items())

    # In Python 3.7+ regular dicts preserve insertion order.
    # For older versions, OrderedDict is needed.
    # We'll use OrderedDict for explicit clarity or if backward compatibility is a concern.
    # Otherwise, a dict comprehension is concise.

    if hasattr(dict, 'copy'): # A simple check for modern Python features (proxies 3.7+)
        return {key: value for key, value in sorted_items}
    else:
        ordered_dict = OrderedDict()
        for key, value in sorted_items:
            ordered_dict[key] = value
        return ordered_dict

