import math

def geometric_mean(numbers):
    if not numbers:
        return 0.0

    product = 1.0
    count = 0
    for num in numbers:
        if num <= 0:
            return 0.0
        product *= num
        count += 1

    if count == 0:
        return 0.0

    # Calculate the nth root of the product
    try:
        mean = product ** (1 / count)
        return float(mean)
    except OverflowError:
        # Handle cases where product becomes too large
        # Use logarithmic approach to prevent overflow
        log_sum = 0.0
        for num in numbers:
            log_sum += math.log(num)
        mean_log = log_sum / count
        return math.exp(mean_log)

